export { anatomy, parts, type SwitchPart } from "./switch.anatomy";
export { connect } from "./switch.connect";
export { getControlEl, getControlId, getHiddenInputId, getLabelId, getRootId } from "./switch.dom";
export { machine } from "./switch.machine";
export type {
  ResolvedSwitchMachineProps,
  SwitchApi,
  SwitchCheckedChangeDetails,
  SwitchMachineProps,
  SwitchSchema,
  SwitchSize,
} from "./switch.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type SwitchPart = "root" | "label" | "control" | "thumb" | "hiddenInput";

export const anatomy: Anatomy<SwitchPart> = createAnatomy("switch").parts(
  "root",
  "label",
  "control",
  "thumb",
  "hiddenInput",
);

export const parts: Record<SwitchPart, AnatomyPart> = anatomy.build();

import { visuallyHiddenStyle } from "../../a11y/visually-hidden";
import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./switch.anatomy";
import { getControlId, getHiddenInputId, getLabelId, getRootId } from "./switch.dom";
import type { SwitchApi, SwitchSchema } from "./switch.types";

export function connect<T extends PropTypes>(
  service: Service<SwitchSchema>,
  normalize: NormalizeProps<T>,
): SwitchApi<T> {
  const { context, prop, state, send, scope } = service;

  const checked = context.get("checked");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");
  const dragProgress = context.get("dragProgress");
  const dragging = dragProgress !== null;
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = state.matches("focused") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const stateAttrs = {
    "data-state": checked ? "checked" : "unchecked",
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-invalid": dataAttr(invalid),
    "data-focus-visible": dataAttr(focusVisible),
    "data-focus-source": focusSource ?? undefined,
    "data-pressed": dataAttr(context.get("pressed")),
    "data-dragging": dataAttr(dragging),
  };

  return {
    checked,
    disabled,
    focusSource,
    focusVisible,
    dragging,

    setChecked(next: boolean): void {
      send({ type: "CHECKED.SET", checked: next });
    },
    toggle(): void {
      send({ type: "CHECKED.TOGGLE" });
    },

    getRootProps: (): T["label"] =>
      normalize.label({
        ...parts.root.attrs,
        ...stateAttrs,
        "data-size": prop("size"),
        id: getRootId(scope),
        dir: prop("dir"),
        style: { userSelect: "none" },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getControlProps: (): T["element"] =>
      normalize.element({
        ...parts.control.attrs,
        ...stateAttrs,
        id: getControlId(scope),
        "aria-hidden": ariaAttr(true),
        // The finger owns the horizontal axis for the duration of the gesture; a
        // scroll container underneath must not take it away mid-drag.
        style: { touchAction: "none" },
      }),

    getThumbProps: (): T["element"] =>
      normalize.element({
        ...parts.thumb.attrs,
        ...stateAttrs,
        "aria-hidden": ariaAttr(true),
        // While dragging the thumb follows the finger; parked, it sits where the
        // state says and the CSS transition carries it there.
        style: dragging ? { "--sui-switch-progress": String(dragProgress) } : undefined,
      }),

    getHiddenInputProps: (): T["input"] =>
      normalize.input({
        ...parts.hiddenInput.attrs,
        id: getHiddenInputId(scope),
        type: "checkbox",
        // A switch is not a checkbox to a screen reader: "on/off", not
        // "checked/unchecked" (APG switch pattern).
        role: "switch",
        style: visuallyHiddenStyle,
        checked,
        disabled,
        required: prop("required"),
        name: prop("name"),
        value: prop("value"),
        form: prop("form"),
        "aria-invalid": ariaAttr(invalid),
        "aria-describedby": prop("describedBy"),
        "aria-readonly": ariaAttr(readOnly),
        onChange(event) {
          if (event.defaultPrevented) return;
          send({ type: "CHECKED.TOGGLE" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.BLUR" });
        },
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "switch";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getHiddenInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "hiddenInput");
}

export function getControlEl(scope: Scope): HTMLElement | null {
  return scope.getById(getControlId(scope));
}

/**
 * The same hidden-input skeleton as the checkbox — the browser owns form
 * association, the label click and the keyboard — plus the one gesture that makes
 * a switch feel like iOS: dragging the thumb across the track.
 *
 * The drag is written here rather than through the `press` primitive because
 * `press` deliberately reports crossings, not positions, and a switch needs the
 * position: the thumb follows the finger, and the release commits to whichever
 * side of the halfway mark it ended on. A drag that never moved is a tap, and a
 * tap must fall through to the native label click rather than toggle twice.
 */

import { addDomEvent, isPrimaryPointer } from "../../dom/event";
import { resolveDir } from "../../dom/text-dir";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { Direction, InputModality } from "../../types";
import { getControlEl } from "./switch.dom";
import type { SwitchSchema } from "./switch.types";

/** How far the finger has to travel before this stops being a tap. */
const DRAG_THRESHOLD_PX = 4;

export const machine: Machine<SwitchSchema> = createMachine<SwitchSchema>({
  props({ props }) {
    return {
      disabled: false,
      invalid: false,
      required: false,
      readOnly: false,
      draggable: true,
      value: "on",
      size: "md",
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      checked: bindable<boolean>(() => ({
        defaultValue: prop("defaultChecked") ?? false,
        value: prop("checked"),
        onChange: (checked) => prop("onCheckedChange")?.({ checked }),
        debugLabel: "switch checked",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      dragProgress: bindable<number | null>(() => ({ defaultValue: null })),
      pressed: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackThumbDrag"],

  on: {
    "CHECKED.TOGGLE": { guard: "isInteractive", actions: ["toggleChecked"] },
    "CHECKED.SET": { guard: "isInteractive", actions: ["setChecked"] },
    "THUMB.DRAG_START": { guard: "isInteractive", actions: ["startDrag"] },
    "THUMB.DRAG": { guard: "isInteractive", actions: ["trackDrag"] },
    "THUMB.DRAG_END": { actions: ["endDrag"] },
    "ROOT.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource"],
      on: { "ROOT.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    },

    actions: {
      toggleChecked({ context }) {
        context.set("checked", (checked) => !checked);
      },
      setChecked({ context, event }) {
        if (event.type === "CHECKED.SET") context.set("checked", event.checked);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
      startDrag({ context }) {
        context.set("pressed", true);
      },
      trackDrag({ context, event }) {
        if (event.type !== "THUMB.DRAG") return;
        context.set("dragProgress", event.progress);
      },
      endDrag({ context, event, prop }) {
        if (event.type !== "THUMB.DRAG_END") return;
        context.set("pressed", false);
        context.set("dragProgress", null);
        // A tap is left to the browser: the label forwards it to the input, which
        // toggles and reports. Handling it here as well would toggle twice.
        if (!event.moved || prop("disabled") || prop("readOnly")) return;
        context.set("checked", event.progress >= 0.5);
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackThumbDrag({ scope, prop, send, context }) {
        const control = getControlEl(scope);
        if (control === null || !prop("draggable")) return;

        let pointerId: number | null = null;
        let startX = 0;
        let moved = false;

        // Resolved once per gesture rather than per frame, the slider's
        // arrangement: `getComputedStyle` on every `pointermove` is a style
        // recalc the drag does not need, and a direction cannot change under a
        // finger that is already down.
        let dragDir: Direction = "ltr";

        const progressAt = (clientX: number): number => {
          const rect = control.getBoundingClientRect();
          if (rect.width === 0) return context.get("checked") ? 1 : 0;
          const ratio = (clientX - rect.left) / rect.width;
          // The track is read in writing order, so the whole gesture mirrors in
          // RTL — where "on" is on the left. Resolved from the node and not from
          // `prop("dir")`: the sheet mirrors the thumb on `:dir(rtl)`, which
          // matches an INHERITED direction, so reading the prop alone drew the
          // thumb one way and committed the value the other.
          const oriented = dragDir === "rtl" ? 1 - ratio : ratio;
          return Math.min(Math.max(oriented, 0), 1);
        };

        const disposers = [
          addDomEvent(control, "pointerdown", (event: PointerEvent) => {
            if (pointerId !== null || !isPrimaryPointer(event)) return;
            pointerId = event.pointerId;
            startX = event.clientX;
            moved = false;
            dragDir = resolveDir(prop("dir"), control);
            try {
              control.setPointerCapture(event.pointerId);
            } catch {
              // A pointer that is already gone still deserves the rest of the
              // sequence; capture is an optimisation, not a precondition.
            }
            send({ type: "THUMB.DRAG_START" });
          }),

          addDomEvent(control, "pointermove", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            if (!moved && Math.abs(event.clientX - startX) < DRAG_THRESHOLD_PX) return;
            moved = true;
            // Only once it is a drag: preventing earlier would eat the tap, and
            // with it the label's click.
            event.preventDefault();
            send({ type: "THUMB.DRAG", progress: progressAt(event.clientX) });
          }),

          addDomEvent(control, "pointerup", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            pointerId = null;
            send({ type: "THUMB.DRAG_END", progress: progressAt(event.clientX), moved });
          }),

          addDomEvent(control, "pointercancel", (event: PointerEvent) => {
            if (event.pointerId !== pointerId) return;
            pointerId = null;
            send({
              type: "THUMB.DRAG_END",
              progress: context.get("checked") ? 1 : 0,
              moved: false,
            });
          }),

          // A drag that ends on the thumb still produces a click on the label.
          // Swallowing it is what keeps the gesture from being undone by the tap
          // the browser reports underneath it.
          addDomEvent(
            control,
            "click",
            (event: MouseEvent) => {
              if (moved) event.preventDefault();
            },
            { capture: true },
          ),
        ];

        return () => {
          for (const dispose of disposers.reverse()) dispose();
        };
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface SwitchCheckedChangeDetails {
  readonly checked: boolean;
}

export type SwitchSize = "sm" | "md";

export interface SwitchMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  /** Controlled. */
  readonly checked?: boolean | undefined;
  readonly defaultChecked?: boolean | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly required?: boolean | undefined;
  /** Blocks the toggle and the drag, and unlike `disabled` leaves the control focusable and still submitted with its form. */
  readonly readOnly?: boolean | undefined;
  readonly name?: string | undefined;
  /** What the hidden input submits while checked. Defaults to `"on"`, as a checkbox does. */
  readonly value?: string | undefined;
  readonly form?: string | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /** The iOS gesture: drag the thumb across the track. On by default. */
  readonly draggable?: boolean | undefined;
  /** Pure presentation: `data-size` on the root, the sheet does the rest. Defaults to `"md"`. */
  readonly size?: SwitchSize | undefined;
  readonly onCheckedChange?: ((details: SwitchCheckedChangeDetails) => void) | undefined;
}

export interface ResolvedSwitchMachineProps extends SwitchMachineProps {
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly required: boolean;
  readonly readOnly: boolean;
  readonly value: string;
  readonly draggable: boolean;
  readonly size: SwitchSize;
}

export interface SwitchSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedSwitchMachineProps;
  context: {
    checked: boolean;
    focusSource: InputModality | null;
    /** 0…1 while dragging, `null` when the thumb is parked at its state. */
    dragProgress: number | null;
    pressed: boolean;
  };
  event:
    | { type: "CHECKED.TOGGLE" }
    | { type: "CHECKED.SET"; checked: boolean }
    | { type: "THUMB.DRAG_START" }
    | { type: "THUMB.DRAG"; progress: number }
    | { type: "THUMB.DRAG_END"; progress: number; moved: boolean }
    | { type: "ROOT.FOCUS" }
    | { type: "ROOT.BLUR" };
  action:
    | "toggleChecked"
    | "setChecked"
    | "captureFocusSource"
    | "clearFocusSource"
    | "startDrag"
    | "trackDrag"
    | "endDrag";
  guard: "isInteractive";
  effect: "trackModality" | "trackThumbDrag";
}

export interface SwitchApi<T extends PropTypes = PropTypes> {
  readonly checked: boolean;
  readonly disabled: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  readonly dragging: boolean;
  setChecked(checked: boolean): void;
  toggle(): void;
  getRootProps(): T["label"];
  getLabelProps(): T["element"];
  getControlProps(): T["element"];
  getThumbProps(): T["element"];
  getHiddenInputProps(): T["input"];
}

/**
 * `<Switch label="Wi-Fi"/>` — five parts, one loop-free tree, and the fork's
 * other minimal end (`Button`, no collection, no `parts` hatch): `SwitchRoot`
 * is already the `<label>`, so the layer only has to place the four children
 * in the order `switch.stories.tsx`'s own `Toggle` helper settled on —
 * `SwitchHiddenInput`, `SwitchLabel`, `SwitchControl > SwitchThumb` — rather
 * than the anatomy's declaration order, which lists `hiddenInput` last.
 *
 * No `parts` escape hatch: this layer sets no attribute of its own on any
 * part for one to win against — `label` only ever reaches `SwitchLabel` as
 * its JSX children, which a spread placed either side of it can never
 * override (React's third `createElement` argument always wins). A consumer
 * who needs to reach `SwitchThumb` or `SwitchHiddenInput` directly still has
 * the parts themselves.
 *
 * `label` is text here and nowhere reads it back: unlike `SelectValueText` or
 * `SliderValueText`, no field of `SwitchApi` is derived from it, so there is
 * no part to teach a default to and no hook for this file to avoid.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  SwitchControl,
  SwitchHiddenInput,
  SwitchLabel,
  SwitchRoot,
  SwitchThumb,
  type UseSwitchProps,
} from "./switch";

export interface SwitchComposedProps
  extends UseSwitchProps,
    Omit<PartProps<"label", UseSwitchProps>, "children"> {
  /** The visible text beside the control. */
  readonly label?: ReactNode;
}

export function Switch(props: SwitchComposedProps): ReactNode {
  const { label, ...root } = props;

  return (
    <SwitchRoot {...root}>
      <SwitchHiddenInput />
      <SwitchLabel>{label}</SwitchLabel>
      <SwitchControl>
        <SwitchThumb />
      </SwitchControl>
    </SwitchRoot>
  );
}

export type {
  SwitchCheckedChangeDetails,
  SwitchMachineProps,
  SwitchSize,
} from "@standarui/core/switch";
export { Switch, type SwitchComposedProps } from "./composed";
export {
  type SwitchApi,
  SwitchControl,
  SwitchHiddenInput,
  SwitchLabel,
  SwitchRoot,
  type SwitchRootProps,
  SwitchThumb,
  type UseSwitchProps,
  useSwitch,
} from "./switch";

import * as switchMachine from "@standarui/core/switch";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type SwitchApi = switchMachine.SwitchApi<ReactPropTypes>;

const SwitchContext = createPartContext<SwitchApi>("Switch");

export interface UseSwitchProps extends switchMachine.SwitchMachineProps, MachineRuntimeProps {}

export function useSwitch(props: UseSwitchProps): SwitchApi {
  return switchMachine.connect(useMachine(switchMachine.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "checked",
  "defaultChecked",
  "disabled",
  "invalid",
  "required",
  "readOnly",
  "name",
  "value",
  "form",
  "draggable",
  "size",
  "describedBy",
  "onCheckedChange",
] as const;

export interface SwitchRootProps extends UseSwitchProps, PartProps<"label", UseSwitchProps> {}

export function SwitchRoot(props: SwitchRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useSwitch({
    ...inheritFromField(machineProps, field),
    ids: { hiddenInput: field?.controlProps.id, ...machineProps.ids },
  });

  return (
    <SwitchContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "label",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </SwitchContext.Provider>
  );
}

export const SwitchLabel: (props: PartProps<"span">) => ReactNode = createPart(SwitchContext, {
  name: "SwitchLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

export const SwitchControl: (props: PartProps<"span">) => ReactNode = createPart(SwitchContext, {
  name: "SwitchControl",
  element: "span",
  props: (api) => api.getControlProps(),
});

export const SwitchThumb: (props: PartProps<"span">) => ReactNode = createPart(SwitchContext, {
  name: "SwitchThumb",
  element: "span",
  props: (api) => api.getThumbProps(),
});

export const SwitchHiddenInput: (props: PartProps<"input">) => ReactNode = createPart(
  SwitchContext,
  { name: "SwitchHiddenInput", element: "input", props: (api) => api.getHiddenInputProps() },
);
